//! The KAGEMUSHA V1 native Poseidon hash (width 3, rate 2, `x^5`, `R_F = 8`,
//! `R_P = 57`, MDS selector 0) over both Pasta fields.
//!
//! # Parameters
//!
//! The round constants and the Cauchy MDS matrix are generated by the Poseidon
//! reference procedure (Grain LFSR, see [`grain`]) for `t = 3`, `R_F = 8`,
//! `R_P = 57`, 255-bit fields and the first secure MDS candidate. They are
//! pinned as `rp57_fp.bin` and `rp57_fq.bin` (65 rows of three canonical
//! 32-byte little-endian constants, then the 3x3 MDS matrix row by row) and
//! regenerated by the tests. These are the constants of
//! `halo2-base`'s `OptimizedPoseidonSpec::<F, 3, 2>::new::<8, 57, 0>()`, which
//! `iroha_core_zk::kagemusha_v1_poseidon` uses today.
//!
//! The pinned round counts are those the protocol compiles today; this module
//! does not by itself qualify their security level.
//!
//! # Permutation
//!
//! The plain (unoptimised) Pow5 permutation: four full rounds, 57 partial
//! rounds, four full rounds; each round adds its constants, applies `x^5` to
//! every word (full) or to word 0 (partial), and multiplies by the MDS matrix.
//! `halo2-base`'s optimised form is an algebraically equal rewriting.
//!
//! # Sponge
//!
//! [`Sponge`] follows the snark-verifier native `Poseidon` semantics that the
//! KAGEMUSHA state hash uses: the initial state is `[2^64, 0, 0]`; buffered
//! input is absorbed in chunks of two into words 1 and 2; a short final chunk
//! is padded with a single 1; when the input length is a multiple of the rate
//! (including zero) one more permutation absorbs the padding block `[1]`; the
//! output is word 1.

pub mod grain;

use std::sync::OnceLock;

use crate::field::{Fp, Fq, PastaField};

/// Permutation width.
pub const WIDTH: usize = 3;
/// Sponge rate.
pub const RATE: usize = 2;
/// Full rounds.
pub const FULL_ROUNDS: usize = 8;
/// Partial rounds.
pub const PARTIAL_ROUNDS: usize = 57;
/// MDS candidate selector of the generation procedure.
pub const SECURE_MDS: usize = 0;

/// Rounds of the permutation (`R_F + R_P`).
pub const ROUNDS: usize = FULL_ROUNDS + PARTIAL_ROUNDS;

/// Pinned constant table for `Fp`.
const RP57_FP: &[u8] = include_bytes!("rp57_fp.bin");
/// Pinned constant table for `Fq`.
const RP57_FQ: &[u8] = include_bytes!("rp57_fq.bin");

/// Number of bytes of a pinned table.
pub const TABLE_BYTES: usize = ROUNDS * WIDTH * 32 + WIDTH * WIDTH * 32;

/// Round constants and MDS matrix of one field.
///
/// The fields are private and sized by the type: exactly [`ROUNDS`] rows of
/// round constants, so [`permute_with`] always runs `R_F + R_P` rounds with
/// the full/partial schedule of the pinned parameters.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PoseidonParams<F> {
    /// `R_F + R_P` rows of round constants.
    round_constants: [[F; WIDTH]; ROUNDS],
    /// The MDS matrix, `state'[i] = sum_j mds[i][j] * state[j]`.
    mds: [[F; WIDTH]; WIDTH],
}

impl<F: PastaField> PoseidonParams<F> {
    /// Parameters from explicit round constants and MDS matrix.
    ///
    /// The shapes are fixed by the types; the values are the caller's
    /// responsibility (use [`PoseidonField::rp57`] for the protocol tables).
    pub fn new(round_constants: [[F; WIDTH]; ROUNDS], mds: [[F; WIDTH]; WIDTH]) -> Self {
        Self {
            round_constants,
            mds,
        }
    }

    /// The `R_F + R_P` rows of round constants, in round order.
    pub fn round_constants(&self) -> &[[F; WIDTH]; ROUNDS] {
        &self.round_constants
    }

    /// The MDS matrix, `state'[i] = sum_j mds[i][j] * state[j]`.
    pub fn mds(&self) -> &[[F; WIDTH]; WIDTH] {
        &self.mds
    }

    /// Parses a pinned table. Returns `None` for a wrong length or a
    /// non-canonical constant.
    pub fn from_table(bytes: &[u8]) -> Option<Self> {
        if bytes.len() != TABLE_BYTES {
            return None;
        }
        let mut words = bytes.chunks_exact(32).map(|chunk| {
            let mut repr = [0u8; 32];
            repr.copy_from_slice(chunk);
            Option::<F>::from(F::from_repr(repr))
        });
        let mut round_constants = [[F::ZERO; WIDTH]; ROUNDS];
        for row in &mut round_constants {
            for v in row.iter_mut() {
                *v = words.next()??;
            }
        }
        let mut mds = [[F::ZERO; WIDTH]; WIDTH];
        for row in &mut mds {
            for v in row.iter_mut() {
                *v = words.next()??;
            }
        }
        Some(Self {
            round_constants,
            mds,
        })
    }

    /// Serialises to the pinned table layout.
    pub fn to_table(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(TABLE_BYTES);
        for v in self
            .round_constants
            .iter()
            .flatten()
            .chain(self.mds.iter().flatten())
        {
            out.extend_from_slice(&v.to_repr());
        }
        out
    }

    /// Regenerates the parameters with the Grain procedure.
    ///
    /// # Panics
    ///
    /// If the generator returned a number of rows other than [`ROUNDS`]
    /// (an internal error).
    pub fn generate() -> Self {
        let (rows, mds) =
            grain::generate_constants::<F, WIDTH>(FULL_ROUNDS, PARTIAL_ROUNDS, SECURE_MDS);
        let round_constants = <[[F; WIDTH]; ROUNDS]>::try_from(rows)
            .unwrap_or_else(|rows| panic!("Grain produced {} rows, expected {ROUNDS}", rows.len()));
        Self {
            round_constants,
            mds,
        }
    }
}

/// Fields with a pinned KAGEMUSHA RP57 table.
pub trait PoseidonField: PastaField {
    /// The parsed pinned parameters.
    ///
    /// # Panics
    ///
    /// If the pinned table embedded in the crate did not parse. The table is a
    /// compile-time constant that the tests parse and regenerate, so this
    /// fails closed instead of substituting other constants.
    fn rp57() -> &'static PoseidonParams<Self>;
}

/// Parses an embedded pinned table, failing closed.
fn pinned<F: PastaField>(table: &[u8], name: &str) -> PoseidonParams<F> {
    PoseidonParams::from_table(table)
        .unwrap_or_else(|| panic!("the pinned {name} Poseidon table is malformed"))
}

impl PoseidonField for Fp {
    fn rp57() -> &'static PoseidonParams<Self> {
        static PARAMS: OnceLock<PoseidonParams<Fp>> = OnceLock::new();
        PARAMS.get_or_init(|| pinned(RP57_FP, "RP57 Fp"))
    }
}

impl PoseidonField for Fq {
    fn rp57() -> &'static PoseidonParams<Self> {
        static PARAMS: OnceLock<PoseidonParams<Fq>> = OnceLock::new();
        PARAMS.get_or_init(|| pinned(RP57_FQ, "RP57 Fq"))
    }
}

/// `x^5`.
#[inline]
fn pow5<F: PastaField>(x: F) -> F {
    let x2 = x.square();
    x2.square() * x
}

/// Multiplies the state by the MDS matrix.
#[inline]
fn apply_mds<F: PastaField>(state: &mut [F; WIDTH], mds: &[[F; WIDTH]; WIDTH]) {
    let s = *state;
    for (out, row) in state.iter_mut().zip(mds.iter()) {
        *out = row[0] * s[0] + row[1] * s[1] + row[2] * s[2];
    }
}

/// The RP57 Pow5 permutation with explicit parameters.
pub fn permute_with<F: PastaField>(state: &mut [F; WIDTH], params: &PoseidonParams<F>) {
    let half_full = FULL_ROUNDS / 2;
    for (round, rc) in params.round_constants.iter().enumerate() {
        for (word, c) in state.iter_mut().zip(rc.iter()) {
            *word += c;
        }
        let full = round < half_full || round >= half_full + PARTIAL_ROUNDS;
        if full {
            for word in state.iter_mut() {
                *word = pow5(*word);
            }
        } else {
            state[0] = pow5(state[0]);
        }
        apply_mds(state, &params.mds);
    }
}

/// The RP57 Pow5 permutation with the pinned parameters of `F`.
pub fn permute<F: PoseidonField>(state: &mut [F; WIDTH]) {
    permute_with(state, F::rp57());
}

/// The KAGEMUSHA native sponge (snark-verifier `NativeLoader` semantics).
#[derive(Clone, Debug)]
pub struct Sponge<F: PoseidonField> {
    state: [F; WIDTH],
    buf: Vec<F>,
}

impl<F: PoseidonField> Default for Sponge<F> {
    fn default() -> Self {
        Self::new()
    }
}

impl<F: PoseidonField> Sponge<F> {
    /// A fresh sponge with state `[2^64, 0, 0]`.
    pub fn new() -> Self {
        Self {
            state: Self::initial_state(),
            buf: Vec::new(),
        }
    }

    fn initial_state() -> [F; WIDTH] {
        [F::from_u128(1u128 << 64), F::ZERO, F::ZERO]
    }

    /// Resets the state and clears buffered input.
    pub fn clear(&mut self) {
        self.state = Self::initial_state();
        self.buf.clear();
    }

    /// Buffers `elements` for absorption.
    pub fn update(&mut self, elements: &[F]) {
        self.buf.extend_from_slice(elements);
    }

    fn absorb_block(&mut self, chunk: &[F]) {
        for (word, input) in self.state[1..].iter_mut().zip(chunk.iter()) {
            *word += input;
        }
        if chunk.len() < RATE {
            self.state[1 + chunk.len()] += F::ONE;
        }
        permute(&mut self.state);
    }

    /// Absorbs the buffered input and returns word 1 of the state.
    ///
    /// The sponge state carries over to later calls, as in the reference.
    pub fn squeeze(&mut self) -> F {
        let buf = core::mem::take(&mut self.buf);
        let exact = buf.len().is_multiple_of(RATE);
        for chunk in buf.chunks(RATE) {
            self.absorb_block(chunk);
        }
        if exact {
            self.absorb_block(&[]);
        }
        self.state[1]
    }
}

/// Hashes one complete preimage with a fresh sponge.
pub fn hash<F: PoseidonField>(preimage: &[F]) -> F {
    let mut sponge = Sponge::new();
    sponge.update(preimage);
    sponge.squeeze()
}

/// Hashes `inputs` under a domain word and the input arity:
/// `hash([domain, len, inputs...])`, as `kagemusha_v1_poseidon::hash` does.
pub fn hash_with_domain<F: PoseidonField>(domain: u64, inputs: &[F]) -> F {
    let mut sponge = Sponge::new();
    // Lengths beyond u64 are impossible for in-memory slices.
    let arity = u64::try_from(inputs.len()).unwrap_or(u64::MAX);
    sponge.update(&[F::from(domain), F::from(arity)]);
    sponge.update(inputs);
    sponge.squeeze()
}

#[cfg(test)]
mod tests {
    use super::*;
    use ff::Field;

    #[test]
    fn pinned_tables_parse_and_regenerate() {
        assert_eq!(RP57_FP.len(), TABLE_BYTES);
        assert_eq!(RP57_FQ.len(), TABLE_BYTES);
        assert_eq!(Fp::rp57().to_table(), RP57_FP);
        assert_eq!(Fq::rp57().to_table(), RP57_FQ);
        assert_eq!(PoseidonParams::<Fp>::generate().to_table(), RP57_FP);
        assert_eq!(PoseidonParams::<Fq>::generate().to_table(), RP57_FQ);
        assert!(PoseidonParams::<Fp>::from_table(&RP57_FP[1..]).is_none());
        let mut bad = RP57_FP.to_vec();
        bad[..32].copy_from_slice(&[0xFF; 32]);
        assert!(PoseidonParams::<Fp>::from_table(&bad).is_none());
    }

    #[test]
    fn parameters_have_a_fixed_shape_and_fail_closed() {
        let p = Fp::rp57();
        assert_eq!(p.round_constants().len(), ROUNDS);
        let rebuilt = PoseidonParams::new(*p.round_constants(), *p.mds());
        assert_eq!(&rebuilt, p);
        assert_eq!(pinned::<Fq>(RP57_FQ, "RP57 Fq"), *Fq::rp57());
        let malformed = std::panic::catch_unwind(|| pinned::<Fp>(&RP57_FP[1..], "test"));
        assert!(malformed.is_err());
        // A different constant changes the permutation.
        let mut constants = *p.round_constants();
        constants[ROUNDS - 1][2] += Fp::ONE;
        let changed = PoseidonParams::new(constants, *p.mds());
        let mut a = [Fp::ONE; WIDTH];
        let mut b = a;
        permute_with(&mut a, p);
        permute_with(&mut b, &changed);
        assert_ne!(a, b);
    }

    #[test]
    fn permutation_and_sponge_behaviour() {
        let mut s = [Fp::ZERO; WIDTH];
        permute(&mut s);
        assert_ne!(s, [Fp::ZERO; WIDTH]);
        let mut t = [Fp::ZERO; WIDTH];
        permute_with(&mut t, Fp::rp57());
        assert_eq!(s, t);
        assert_eq!(apply_identity(), [Fp::ONE, Fp::from(2u64), Fp::from(3u64)]);
        assert_eq!(pow5(Fq::from(2u64)), Fq::from(32u64));
        let a = hash(&[Fp::from(7u64), Fp::from(9u64)]);
        let mut sponge = Sponge::<Fp>::default();
        sponge.update(&[Fp::from(7u64)]);
        sponge.update(&[Fp::from(9u64)]);
        assert_eq!(sponge.squeeze(), a);
        sponge.clear();
        sponge.update(&[Fp::from(7u64), Fp::from(9u64)]);
        assert_eq!(sponge.squeeze(), a);
        assert_ne!(hash::<Fp>(&[]), hash(&[Fp::ZERO]));
        assert_eq!(
            hash_with_domain(5, &[Fq::ONE]),
            hash(&[Fq::from(5u64), Fq::ONE, Fq::ONE])
        );
    }

    fn apply_identity() -> [Fp; WIDTH] {
        let mut st = [Fp::ONE, Fp::from(2u64), Fp::from(3u64)];
        let id = [
            [Fp::ONE, Fp::ZERO, Fp::ZERO],
            [Fp::ZERO, Fp::ONE, Fp::ZERO],
            [Fp::ZERO, Fp::ZERO, Fp::ONE],
        ];
        apply_mds(&mut st, &id);
        st
    }
}
